const {test}=require('node:test');const assert=require('node:assert/strict');const {createHandler,capability}=require('../api/app-actions.js');
process.env.RANCH_VIEW_WRITE_KEY='browser-secret';process.env.RANCH_VIEW_READ_KEY='read-secret';
function fixture(){const records=new Map();const store={get:async p=>records.has(p)?{statusCode:200,stream:new Response(JSON.stringify(records.get(p))).body}:null,put:async(p,s)=>{if(records.has(p))throw Error('exists');records.set(p,JSON.parse(s));},list:async({prefix})=>({blobs:[...records.keys()].filter(p=>p.startsWith(prefix)).map(pathname=>({pathname,uploadedAt:new Date().toISOString()}))})};const handler=createHandler(store);async function request(method,key,body,query=''){let result;await handler({method,url:'/api/app-actions'+query,headers:{authorization:'Bearer '+key,host:'ranch.test'},body},{setHeader(){},end(s){result={status:this.statusCode,body:JSON.parse(s)};}});return result;}return {records,request};}
const target={sessionId:'session-1234567890',documentId:'document-1234567890',slug:'/playground',search:'',buildId:'test-build'};
const command=()=>({id:'command-1234567890',target,action:'board.move',arguments:{cell:2},expectedRevision:3,expiresAt:Date.now()+30000});
function view(){return {sharing:true,visibility:'visible',receivedAt:new Date().toISOString(),actions:{target:{...target,enabled:true},providers:[{revision:3,actions:[{name:'board.move'}]}]}};}
test('observation credential cannot mutate; paired browser polls; receipt is immutable',async()=>{const {request,records}=fixture();records.set('ranch-view/v1/'+target.sessionId+'.json',view());const c=command();assert.equal((await request('POST','read-secret',{command:c})).status,403);assert.equal((await request('POST','browser-secret',{command:c})).status,403);assert.equal((await request('POST',capability('browser-secret'),{command:c})).status,202);assert.equal((await request('POST',capability('browser-secret'),{command:c})).status,200);assert.equal((await request('POST',capability('browser-secret'),{command:{...c,arguments:{cell:4}}})).status,409);const q='?sessionId='+target.sessionId;assert.equal((await request('GET','read-secret',null,q)).status,403);assert.equal((await request('GET','browser-secret',null,q)).body.commands.length,1);assert.equal((await request('GET','read-secret',null,q+'&id='+c.id)).body.receipt.status,'queued');await request('POST','browser-secret',{kind:'started',sessionId:target.sessionId,id:c.id});assert.equal((await request('GET','read-secret',null,q+'&id='+c.id)).body.receipt.status,'running');await request('POST','browser-secret',{kind:'receipt',sessionId:target.sessionId,receipt:{id:c.id,status:'succeeded',afterRevision:4}});assert.equal((await request('GET','browser-secret',null,q)).body.commands.length,0);assert.equal((await request('GET','read-secret',null,q+'&id='+c.id)).body.receipt.status,'succeeded');});
test('stale, hidden, paused, wrong-build and revision-conflicting targets rejected',async()=>{for(const change of [v=>v.receivedAt=new Date(0).toISOString(),v=>v.visibility='hidden',v=>v.sharing=false,v=>v.actions.target.buildId='old',v=>v.actions.providers[0].revision=4]){const {request,records}=fixture();const v=view();change(v);records.set('ranch-view/v1/'+target.sessionId+'.json',v);assert.equal((await request('POST',capability('browser-secret'),{command:command()})).status,409);}});
